const CFG = {
  mode: 'keys',
  project_id: '479073796a6095e8c10e35.09051894',
  filter_tags: '',
  filter_untranslated: 0
};
const BASE = 'https://api.lokalise.com/api2';
if (CFG.mode === 'projects') { return [{ json: { mode: 'projects', url: BASE + '/projects?limit=100&include_statistics=1' } }]; }
if (CFG.mode === 'languages') { return [{ json: { mode: 'languages', url: BASE + '/projects/' + CFG.project_id + '/languages?limit=500' } }]; }
let qs = 'include_translations=1&include_comments=1&disable_references=1&filter_archived=exclude&limit=500&pagination=cursor';
if (CFG.filter_tags) { qs += '&filter_tags=' + encodeURIComponent(CFG.filter_tags); }
if (CFG.filter_untranslated) { qs += '&filter_untranslated=1'; }
return [{ json: { mode: 'keys', url: BASE + '/projects/' + CFG.project_id + '/keys?' + qs } }];

const mode = $('Config').first().json.mode;
const pages = $input.all();
const errors = [];
if (mode !== 'keys') { return [{ json: { mode, pages: pages.map(p => ({ status: p.json.statusCode, body: p.json.body })) } }]; }
let seen = 0; const rows = [];
const str = v => (v && typeof v === 'object') ? JSON.stringify(v) : String(v == null ? '' : v);
for (const p of pages) {
  const j = p.json; if (j.statusCode && j.statusCode >= 400) { errors.push({ status: j.statusCode, body: JSON.stringify(j.body || '').slice(0, 300) }); continue; }
  const keys = (j.body && j.body.keys) || [];
  for (const k of keys) {
    seen++;
    if (k.is_archived) continue;
    const tr = k.translations || []; const en = tr.find(t => t.language_iso === 'en');
    const ens = en ? str(en.translation) : '';
    if (!ens.trim()) continue;
    const row = { k: (k.key_name && (k.key_name.web || k.key_name.other)) || String(k.key_id), id: k.key_id, en: ens, pl: k.is_plural ? 1 : 0, t: {}, m: {} };
    row.d = String(k.description || '').slice(0, 500); row.cl = Number(k.char_limit || 0);
    row.tg = Array.isArray(k.tags) ? k.tags.map(String) : [];
    row.c = (k.comments || []).map(x => String(x.comment || '')).filter(Boolean).join(' | ').slice(0, 300);
    for (const t of tr) {
      if (t.language_iso === 'en') continue; const v = str(t.translation); if (!v.trim()) continue;
      row.t[t.language_iso] = v; row.m[t.language_iso] = (t.modified_at || '') + '|' + (t.is_reviewed ? 1 : 0) + '|' + (t.is_unverified ? 1 : 0) + '|' + (t.modified_by_email || '');
    }
    rows.push(row);
  }
}
return [{ json: { mode, keys_seen: seen, rows_kept: rows.length, pages: pages.length, errors, rows } }];
